head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/alert_error.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/mgt.js");
scwin.vScrenID = 'ULDMGT40020.xml';
scwin.tmpUpDepNm = "";
scwin.tmpUpDepCd = "";
scwin.tmpDepNm = "";
scwin.tmpDepCd = "";
scwin.tmpChrgIndNm = "";
scwin.tmpDutyGrpTpCd = "";
scwin.tmpSndlocTpCd = "";
scwin.tmpKclicUsrTpId = "";
scwin.logicTp = "0"; //0:신규, 1:수정, 2:삭제
scwin.isExistDepInfo = false;
scwin.usrPosition = 1; //트랜젝션 후에 사용자리스트를 리로드 하고 선택 위치를 이동 시키기 위해
scwin.position = 1; //사용자포지션
scwin.isSameDept = true;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.getDataSetData = function() {
    mdsPdept.DataID = "/depusr.do?method=getPdepLst&outputMessageId=tbld_dep_mng" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    mdsPdept.reset();
    mdsDepLst.DataID = "/depusr.do?method=getDepTreeLst&outputMessageId=tbld_dep_mng" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    mdsDepLst.reset();
    $c.cm.ShowWin(mxmGusrLst);
};
scwin.setDataSet = function() {
    mdsDepLst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbld_dep_mng"; //전체부서조직
    mdsDepLst.reset();
    mdsPdept.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbld_dep_mng"; //본부급 목록
    mdsPdept.reset();
    mdsDeptSave.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbld_dep_mng"; //저장하려는 객체의 데이터셋
    mdsDeptSave.reset();
    mdsDepHist.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbld_dep_mng"; //저장하려는 객체의 데이터셋
    mdsDepHist.reset();
    mdsMemberCheck.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbld_dep_mng"; //저장하려는 객체의 데이터셋
    mdsMemberCheck.reset();
};


//tp 1:상위부서 목록 2:히스토리
scwin.schMyDept = function(tp, row) {
    var vDept = '';
    if (tp == 1) {
        vDept = mdsPdept.getCellData(row, "DEP_CD");
    } else {
        vDept = mdsDepHist.getCellData(row, "DEP_CD");
    }
    var tmpVal1;
    for (var i = 0; i <= mdsDepLst.getTotalRow(); i++) {
        tmpVal1 = mdsDepLst.getCellData(i, "DEP_CD");
        if (tmpVal1 == vDept) {
            mdsDepLst.setRowPosition(i, 0);
        }
    }
};
scwin.schDept = function(ver) {
    var tmpVal1;
    var tmpVal2;
};


//	ver 0:신규, 1:수정, 2:삭제
scwin.setDeptInfo = function(ver) {
    scwin.logicTp = ver;
    if (ver == "0") {
        lblStrtDD.style.display = "";
        lblEndDD.style.display = "none";
        if (scwin.isSameDept) {
            txtUpDeptNm.setValue(scwin.tmpUpDepNm);
            txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        } else {
            txtUpDeptNm.setValue(scwin.tmpDepNm);
            txtUpDeptCd.setValue(scwin.tmpDepCd);
        }
        txtChrgIndNm.setValue("");
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadOnly(true);
        txtUpDeptCd.setReadOnly(true);
        txtDeptNm.setReadOnly(false);
        txtDeptCd.setReadOnly(false);
        txtDeptNm.setValue("");
        txtDeptCd.setValue("");
    } else if (ver == 1) {
        lblStrtDD.style.display = "";
        lblEndDD.style.display = "none";
        txtUpDeptNm.setValue(scwin.tmpUpDepNm);
        txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        txtDeptNm.setValue(scwin.tmpDepNm);
        txtDeptCd.setValue(scwin.tmpDepCd);
        txtChrgIndNm.setValue(scwin.tmpChrgIndNm);
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadOnly(true);
        txtUpDeptCd.setReadOnly(false);
        txtDeptNm.setReadOnly(false);
        txtDeptCd.setReadOnly(false);
    } else {
        lblStrtDD.style.display = "none";
        lblEndDD.style.display = "";
        txtUpDeptNm.setValue(scwin.tmpUpDepNm);
        txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        txtDeptNm.setValue(scwin.tmpDepNm);
        txtDeptCd.setValue(scwin.tmpDepCd);
        txtChrgIndNm.setValue(scwin.tmpChrgIndNm);
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadOnly(true);
        txtUpDeptCd.setReadOnly(true);
        txtDeptNm.setReadOnly(true);
        txtDeptCd.setReadOnly(true);
    }
};
scwin.setDefault = function() {
    lblEndDD.style.display = "none";
};
scwin.doDepSave = function() {
    if (scwin.valueCheck()) {
        if (scwin.setSaveDeptInfo()) {
            if (scwin.logicNdeptCheck()) {
                var url = "/depusr.do?method=saveDeptInfo";
                var keyVal = "JSP(I:pInput=mdsDeptSave)";
                trSave.Action = url;
                trSave.KeyName = "toinb_dataid4";
                trSave.KeyValue = keyVal;
                trSave.post();
            }
        } else {
            $c.win.alert('팀 정보 세팅 오류!');
        }
    }
};
scwin.doHistSave = function() {
    var msg1 = "수정된 사항을 저장하시겠습니까?";
    var msg2 = "\r\n(체크된 Row는 수정과 상관 없이 삭제 됩니다.)";
    if (scwin.isHistChecked()) msg1 = msg1 + msg2;
    if (confirm(msg1)) {
        if (scwin.doDeleteHist()) {
            var url = "/depusr.do?method=saveHistInfo";
            var keyVal = "JSP(I:pInput=mdsDepHist)";
            trSave.Action = url;
            trSave.KeyName = "toinb_dataid4";
            trSave.KeyValue = keyVal;
            trSave.post();
        }
    }
};




//순서대로 지우면 하나가 지워지면서 밑엣게 위로 올라옴. 그래서 거꾸로 지움
scwin.doDeleteHist = function() {
    for (i = mdsDepHist.getTotalRow(); i >= 1; i--) {
        if (mdsDepHist.getCellData(i, "CHK_FLAG") == 1) {
            $c.cp.removeRow(mdsDepHist, i);
        }
    }
    return true;
};
scwin.isHistChecked = function() {
    var isChecked = false;
    return isChecked;
};
scwin.logicNdeptCheck = function() {
    if (scwin.logicTp == "0") {
        if (confirm(txtDeptNm.getValue() + "(" + txtDeptCd.getValue() + ")를 신규생성 하시겠습니까?")) {
            return true;
        } else return false;
    } else if (scwin.logicTp == "1") {
        var old_dep_cd = mdsDeptSave.getCellData(1, "DEP_CD");
        var new_dep_cd = mdsDeptSave.getCellData(1, "NEW_DEP_CD");
        if (old_dep_cd != new_dep_cd) {
            if (confirm('팀코드가 변경되었습니다. 계속진행하시겠습니까?')) {

            } else {
                return false;
            }
        }
        var msg = "[" + scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")]에서 [" + txtDeptNm.getValue() + "](으)로 변경 하시겠습니까?";
        if (scwin.tmpDepNm == txtDeptNm.getValue()) {
            msg = scwin.tmpDepNm + "(" + scwin.tmpDepCd + ") 정보를 변경 하시겠습니까?";
        }
        if (confirm(msg)) {
            return true;
        } else return false;
    } else if (scwin.logicTp == "2") {
        if (confirm(scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")를 삭제 하시겠습니까?")) {
            return true;
        } else return false;
    }
};
scwin.valueCheck = function() {
    if (meAskDate.getValue() == "") {
        $c.win.alert("[시작일/종료일]은 필수입니다.");
        return false;
    }
    if (scwin.tmpDepCd == "" || scwin.tmpDepNm == "") {
        $c.win.alert("팀코드와 팀명은 필수입니다.");
        return false;
    }
    return true;
};
scwin.setSaveDeptInfo = function() {
    try {
        if (mdsDeptSave.getTotalRow() != 0) {
            mdsDeptSave.removeAll();
        }
        mdsDeptSave.insertRow();
        mdsDeptSave.setCellData(1, "DEP_CD", scwin.tmpDepCd);
        mdsDeptSave.setCellData(1, "NEW_DEP_CD", txtDeptCd.getValue());
        mdsDeptSave.setCellData(1, "UP_DEP_CD", txtUpDeptCd.getValue());
        mdsDeptSave.setCellData(1, "DEP_NM", txtDeptNm.getValue());
        mdsDeptSave.setCellData(1, "CHRG_IND_NM", txtChrgIndNm.getValue());
        mdsDeptSave.setCellData(1, "REMK", txtRemk.Text);
        mdsDeptSave.setCellData(1, "DUTY_GRP_TP_CD", txtDutyGrpTpCd.getValue());
        mdsDeptSave.setCellData(1, "SNDLOC_TP_CD", txtSndlocTpCd.getValue());
        mdsDeptSave.setCellData(1, "KCLIC_USR_TP_ID", txtKclicUsrTpId.getValue());
        mdsDeptSave.setCellData(1, "ASK_DATE", meAskDate.getValue());
        mdsDeptSave.setCellData(1, "LOGIC_TP", scwin.logicTp);
        return true;
    } catch (err) {
        $c.win.alert(err);
        return false;
    }
};
scwin.resetList = function() {
    mdsDepLst.reset();
};


//ver
scwin.getDepHistLst = function(ver) {
    var url = "/depusr.do?method=getDepHistLst&outputMessageId=tbld_dep_mng" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&dep_info=" + ver;
    mdsDepHist.DataID = encodeURI(url);
    mdsDepHist.reset();
};
scwin.clearEditTextBox = function() {
    txtUpDeptNm.setValue('');
    txtUpDeptCd.setValue('');
    txtDeptNm.setValue('');
    txtDeptCd.setValue('');
    txtChrgIndNm.setValue('');
    txtDutyGrpTpCd.setValue('');
    txtSndlocTpCd.setValue('');
    txtKclicUsrTpId.setValue('');
};
scwin.checkMemberExist = function() {
    var url = "/depusr.do?method=getDepMemberCnt&outputMessageId=tbld_dep_team_cnt" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&DEP_CD=" + txtDeptCd.getValue();
    mdsMemberCheck.DataID = encodeURI(url);
    mdsMemberCheck.reset();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox_01(panel_5);
    scwin.setDefault();
    scwin.setDataSet();
    scwin.getDataSetData();
};
scwin.imgDelDate_onclick = function() {
    popUpCalendar(tboxAskDate, 'meAskDate', 'yyyymmdd');
};
scwin.mdsDepLst_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, mxmGusrLst);
    mdsDepLst.setRowPosition(scwin.usrPosition, 0);
};
scwin.mgPdept_OnClick = function(row, colid) {
    scwin.schMyDept(1, row);
};
scwin.mgPdept_OnKeyPress = function(keycode) {
    if (keycode == '13') {
        tbAuthSch.style.display = "";
        tbAuthSch.focus();
    }
};
scwin.mdsPdept_OnLoadCompleted = function(rowcount) {

};
scwin.btnNew_onclick = function() {
    if (confirm("동급부서로 등록하려면 '예', 하위부서로 등록하려면 '취소'를 선택하세요.")) {
        scwin.isSameDept = true;
    } else {
        scwin.isSameDept = false;
    }
    scwin.setDeptInfo("0");
};
scwin.btnModify_onclick = function() {
    scwin.setDeptInfo("1");
};
scwin.btnDelete_onclick = function() {
    scwin.setDeptInfo("2");
};
scwin.btnAddSave_onclick = function() {
    var dep_cd = txtDeptCd.getValue();
    if (scwin.logicTp == '') {
        $c.win.alert("①, ②, ③ 중 하나의 기능을 먼저 클릭해야 합니다.");
    }
    if (dep_cd == '') {
        $c.win.alert("부서코드는 필수 입니다.");
        txtDeptCd.focus();
    } else {
        if (scwin.logicTp == '2') {
            scwin.checkMemberExist();
        } else {
            scwin.doDepSave();
        }
    }
};
scwin.trSave_OnSuccess = function() {
    $c.win.alert('처리완료');
    scwin.resetList();
};
scwin.trSave_OnFail = function() {
    $c.win.alert('trSave.OnFail()');
};
scwin.tbSch_onkeydown = function() {
    if (window.event.keyCode == 13) {
        if (!scwin.isExistDepInfo) {
            scwin.position = 1;
        }
        scwin.schDept(tbSch.getValue());
    } else {
        positon = 1;
        scwin.isExistDepInfo = false;
    }
};
scwin.txtDeptCd_onblur = function() {
    txtChrgIndNm.setValue(txtDeptCd.getValue());
};
scwin.mdsDepHist_OnLoadCompleted = function(rowcount) {

};
scwin.txtSrchDepHist_onkeydown = function() {
    if (window.event.keyCode == 13) scwin.getDepHistLst(txtSrchDepHist.getValue());
};
scwin.mdsDepLst_OnRowPosChanged = function(row) {
    scwin.tmpUpDepNm = mdsDepLst.getCellData(row, "UP_DEP_NM");
    scwin.tmpUpDepCd = mdsDepLst.getCellData(row, "UP_DEP_CD");
    scwin.tmpDepNm = mdsDepLst.getCellData(row, "DEP_NM");
    scwin.tmpDepCd = mdsDepLst.getCellData(row, "DEP_CD");
    scwin.tmpChrgIndNm = mdsDepLst.getCellData(row, "CHRG_IND_NM");
    scwin.tmpDutyGrpTpCd = mdsDepLst.getCellData(row, "DUTY_GRP_TP_CD");
    scwin.tmpSndlocTpCd = mdsDepLst.getCellData(row, "SNDLOC_TP_CD");
    scwin.tmpKclicUsrTpId = mdsDepLst.getCellData(row, "KCLIC_USR_TP_ID");
    scwin.clearEditTextBox();
};
scwin.img_1_onclick = function() {
    mdsDepLst.reset();
};
scwin.btnHistSave_onclick = function() {
    scwin.doHistSave();
};
scwin.mxmGusrLst_OnLButtonDown = function(type, row, colid, x, y) {
    scwin.usrPosition = row;
    scwin.getDepHistLst(scwin.tmpDepCd);
};
scwin.mgDepHist_OnLButtonDown = function(row, colid, xpos, ypos) {
    scwin.schMyDept(2, row);
};
scwin.txtUpDeptCd_onkeyup = function() {
    var ver = txtUpDeptCd.getValue();
    var deptCd = '';
    if (ver.length == 4) {
        for (var i = 1; i <= mdsDepLst.getTotalRow(); i++) {
            deptCd = mdsDepLst.getCellData(i, "DEP_CD");
            if (ver == deptCd) {
                txtUpDeptNm.setValue(mdsDepLst.getCellData(i, "DEP_NM"));
                break;
            }
        }
    }
};
scwin.mdsMemberCheck_OnLoadCompleted = function(rowcount) {
    var cnt = 0;
    if (rowcount != 0) {
        cnt = mdsMemberCheck.getCellData(1, "COUNT");
        if (cnt != 0) {
            $c.win.alert("팀원이 있는 팀은 삭제 할 수 없습니다.");
        } else {
            scwin.doDepSave();
        }
    }
};
